INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ac670f5ef5dea3bcc328be1be888f671', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_circuits', 'Alternating Current', 'Peak and RMS values', '[]', '["peak voltage","RMS voltage","sinusoidal AC","sqrt2","voltage conversion"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'In a sinusoidal AC circuit the peak voltage is $170\,\text{V}$. What is the RMS voltage (in volts, rounded to the nearest integer)?', '[]', '120', 'For a sinusoid, $V_{\text{rms}} = V_{\text{peak}}/\sqrt{2} = 170/1.414 \approx 120.3\,\text{V}$, which rounds to $120\,\text{V}$.', '["Step 1: Recall the relation $V_{\\text{rms}} = V_{\\text{peak}}/\\sqrt{2}$ for a sinusoidal waveform.", "Step 2: Substitute $V_{\\text{peak}} = 170\\,\\text{V}$ to get $V_{\\text{rms}} = 170/\\sqrt{2}$.", "Step 3: Compute $170/1.414 \\approx 120.3\\,\\text{V}$ and round to the nearest integer, $120\\,\\text{V}$."]', 'V_{\text{rms}} = V_{\text{peak}}/\sqrt{2}', 'physics.ac.rms_peak_conversion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:44:57.678Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ac6b2897d4985445f7495a44663802a3', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_pn', 'Semiconductor Electronics', 'p-n junction diode', '[]', '["p-n junction","forward bias","minority carrier concentration","thermal voltage","exponential relation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A silicon p‑n junction diode is forward biased with a voltage of $0.6\,\text{V}$. At room temperature the thermal voltage $V_T = \frac{kT}{q} \approx 26\,\text{mV}$. What is the ratio of the minority‑carrier concentration at the edge of the depletion region on the n‑side to that in the neutral p‑region?', '["$10^{10}$", "$10^{5}$", "$10^{2}$", "1"]', '$10^{10}$', 'In forward bias the minority‑carrier concentration at the edge of the depletion region is $n_{p}(0)=n_{p0}\,e^{qV/kT}=n_{p0}e^{V/V_T}$. Substituting $V=0.6\,\text{V}$ and $V_T=0.026\,\text{V}$ gives $e^{0.6/0.026}\approx e^{23.08}\approx 10^{10}$, so the ratio is $10^{10}$.', '["Step 1: Write the relation $n_{p}(0)=n_{p0}\\,e^{qV/kT}$ for forward bias.", "Step 2: Replace $qV/kT$ by $V/V_T$ and insert $V=0.6\\,\\text{V}$, $V_T=0.026\\,\\text{V}$.", "Step 3: Evaluate $e^{0.6/0.026}\\approx e^{23.08}\\approx 10^{10}$."]', '$n = n_0 e^{qV/kT}$', 'physics.semiconductor.pn_forward_ratio', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:35:03.450Z', -1);
