$$,', '["C3 pathway", "C4 pathway", "CAM pathway", "Crassulacean acid metabolism pathway"]', 'C4 pathway', 'Step 1: Recall the C4 pathway and its type of photosynthesis.', '["Step 1: Recall the C4 pathway and its type of photosynthesis."]', '', 'biology.photosynthesis_in_higher_plants.c4_pathway', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:23.727Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae5c665b96c44d5e4082e461bd657dcf', 'NEET', '11', 'Biology', 'bio_11_neet_digestion', 'Digestion and Absorption', 'Peristalsis and segmentation movements', '[]', '["peristalsis","segmentation","small intestine","motility","enteric nervous system"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 3, -1.0, 'Which statement correctly distinguishes peristalsis from segmentation movements in the small intestine?', '["Peristalsis propels the chyme unidirectionally while segmentation primarily mixes the contents.", "Peristalsis mixes the chyme while segmentation propels it forward.", "Both are rhythmic, but peristalsis occurs only in the esophagus.", "Segmentation is controlled by the enteric nervous system, whereas peristalsis is not."]', 'Peristalsis propels the chyme unidirectionally while segmentation primarily mixes the contents.', 'Peristalsis generates coordinated wave‑like contractions that move the intestinal contents forward. Segmentation consists of alternating contractions that churn and mix the chyme without net movement. Hence the first option correctly describes the functional difference.', '["Step 1: Recall that peristalsis is a propulsive wave of contraction.", "Step 2: Recall that segmentation creates localized contractions that mix the contents.", "Step 3: Match the description to the option that states peristalsis propels and segmentation mixes."]', '', 'biology.digestive.peristalsis_vs_segmentation', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:11.707Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae5e91c9859c90fad91574882108153e', 'Board', '8', 'Mathematics', 'mat_8_rational_numbers', 'Rational Numbers', 'Additive Inverse', '[]', '["additive inverse","rational numbers","negative sign","fraction"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 2, 0.0, 'What is the additive inverse of the rational number $\frac{7}{5}$?', '["-\\frac{7}{5}", "\\frac{7}{5}", "1", "0"]', '-\frac{7}{5}', 'The additive inverse of a number $a$ is $-a$. Changing the sign of $\frac{7}{5}$ gives $-\frac{7}{5}$.', '["Step 1: Identify the given rational number $\\frac{7}{5}$.", "Step 2: Apply the definition of additive inverse (multiply by -1).", "Step 3: Write the result as $-\\frac{7}{5}$."]', 'Additive inverse of $a$ is $-a$', 'math.rational.additive_inverse', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:04.349Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae60735d9ef2a48358e0f765ac174f2a', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Hormonal regulation of gonadotropins', '[]', '["GnRH","LH","FSH","anterior pituitary","pulse frequency","estrogen feedback"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'Which of the following statements correctly describes the regulation of LH and FSH secretion by gonadotropin‑releasing hormone (GnRH) in the female reproductive axis?', '["GnRH stimulates the anterior pituitary to secrete LH and FSH; the frequency of GnRH pulses determines the relative amounts of LH and FSH released.", "GnRH directly stimulates the ovaries to produce LH and FSH.", "GnRH inhibits LH secretion while stimulating FSH secretion.", "GnRH secretion is inhibited by high estrogen levels throughout the menstrual cycle."]', 'GnRH stimulates the anterior pituitary to secrete LH and FSH; the frequency of GnRH pulses determines the relative amounts of LH and FSH released.', 'GnRH acts on the gonadotrophs of the anterior pituitary, causing release of both LH and FSH. The pattern of GnRH pulses (high frequency → more LH; low frequency → more FSH) modulates the relative secretion. GnRH does not act directly on the ovaries, nor does it inhibit LH while stimulating FSH.', '["Step 1: Recall that GnRH is released from the hypothalamus and acts on the anterior pituitary.", "Step 2: Recognize that both LH and FSH are secreted in response to GnRH, with pulse frequency governing their relative levels."]', '', 'biology.reproduction.gnRH_regulation', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:12:16.497Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae65ac64fb2c52fd4dbd88bb04a19b88', 'JEEMains', '12', 'Physics', 'phy_12_jm_emi', 'Electromagnetic Induction', 'LR circuit growth decay of current', '[]', '["LR circuit","time constant","growth of current","exponential rise"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, 0.0, 'In an LR circuit, the current grows to 63% of its maximum value in time $\tau$. What is the value of $\tau$?', '[]', '1', 'Time constant $\tau = L/R$, defines 63% growth time.', '["$I = I_0(1 - e^{-t/\\tau})$", "At $t = \\tau$, $I = 0.63I_0$"]', '\tau = L/R', 'physics.emi.time_constant_definition', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:48.180Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae66522a652085159e649c51c9ede173', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Application of Integrals', 'Area between curve and $x$‑axis', '["math_12_jm_analytic_geometry"]', '["definite integral","area under curve","odd function","root finding"]', 1, 0, '[]', 'Integer', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 5, 0.0, 'Calculate the total area enclosed between the curve $y = x^{3} - 3x$ and the $x$‑axis in the interval $[-2,\,2]$.', '[]', '5', 'The curve crosses the $x$‑axis at $x = -\sqrt{3},\,0,\,\sqrt{3}$. Splitting the integral at these points and integrating $|x^{3}-3x|$ gives $\int_{-2}^{-\sqrt{3}}\!-(x^{3}-3x)dx + \int_{-\sqrt{3}}^{0}\!(x^{3}-3x)dx + \int_{0}^{\sqrt{3}}\!-(x^{3}-3x)dx + \int_{\sqrt{3}}^{2}\!(x^{3}-3x)dx = 5$ square units.', '["Step 1: Find the real roots of $x^{3}-3x=0$ to locate sign changes.", "Step 2: Divide the interval $[-2,2]$ into sub‑intervals where the function keeps a constant sign.", "Step 3: Set up the definite integrals of $\\pm (x^{3}-3x)$ on each sub‑interval.", "Step 4: Evaluate each integral and add the absolute values.", "Step 5: Sum the contributions to obtain the total area."]', 'Area = \int_{a}^{b} |f(x)|\,dx', 'math.calculus.area_absolute', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:32.969Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae6a98ec6251eb2a687147ac2321e4e0', 'Board', '9', 'Mathematics', 'math_9_statistics', 'Statistics', 'Mean of a data set', '[]', '["mean","average","data_collection","summation"]', 0, 0, '[]', 'MCQ', NULL, 0, 960, 'CLASS_9_BASIC', 3, 0.0, 'The data set {12, 15, 15, 18, 21} is collected. What is the mean of the data?', '["16.2", "15.0", "15.5", "17.0"]', '16.2', 'Mean $=\frac{\sum \text{values}}{\text{number of values}} = \frac{12+15+15+18+21}{5}=\frac{81}{5}=16.2$. The 15.0 option forgets to include the 12 and 21, while 15.5 is a rounding error.', '["Step 1: Add all numbers: $12+15+15+18+21 = 81$.", "Step 2: Count the total entries: $5$.", "Step 3: Divide: $81/5 = 16.2$."]', '$\text{Mean}=\frac{\sum x_i}{n}$', 'math.statistics.mean_calculation', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:59:37.533Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae7107bf75bc683ce8563fbcd0cb388d', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Lamarckism vs Darwinism', '[]', '["natural_selection","lamarckism","darwinism","variation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'NEET_MEDIUM', 2, -1.0, 'Which concept is central to Darwinism but absent in Lamarckism?', '["Inheritance of acquired characters", "Use and disuse of organs", "Survival of the fittest", "Direct effect of environment"]', 'Survival of the fittest', 'Darwin emphasized natural selection, not inheritance of acquired traits.', '["Lamarck: Acquired traits are passed on.", "Darwin: Natural selection selects fittest."]', '', 'biology.evolution.theory_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:36:30.361Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae7385e31a517b039d95158fe40a1c5c', 'JEEMains', '12', 'Physics', 'phy_12_jm_wave_optics', 'Wave Optics', 'Conditions for maxima and minima', '[]', '["double slit","interference maxima","path difference","diffraction"]', 0, 0, '[]', 'MCQ', NULL, 0, 2300, 'JEE_MAINS_HARD', 4, -1.0, 'In a double‑slit experiment, the slit separation is \(d = 0.30\) mm and the wavelength of light is \(\lambda = 600\) nm. The screen is placed \(D = 2.0\) m from the slits. What is the angular position (in degrees) of the second‑order bright fringe?', '["0.115°", "0.229°", "0.458°", "0.915°"]', '0.229°', 'For bright fringes, \(d\sin\theta = m\lambda\). With \(m=2\), \(\sin\theta = \frac{2\times600\times10^{-9}}{0.30\times10^{-3}} = 0.004\). Hence \(\theta \approx \arcsin(0.004) = 0.229°\).', '["Step 1: Write the condition for bright fringes: \\(d\\sin\\theta = m\\lambda\\).", "Step 2: Substitute \\(m=2\\), \\(d=0.30\\) mm, and \\(\\lambda=600\\) nm.", "Step 3: Compute \\(\\sin\\theta = 0.004\\).", "Step 4: Convert \\(\\theta\\) to degrees to obtain \\(0.229°\\)."]', 'd\sin\theta = m\lambda', 'physics.optics.double_slit_maxima', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:23.785Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae74b484a4f8468ede0da9f0bd3dbd17', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Sets and Venn Diagrams – Applications in probability counting', '[]', '["Venn diagram","inclusion‑exclusion","probability","counting"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'In a group of 60 students, 35 study Mathematics, 28 study Physics, and 12 study both subjects. How many students study neither Mathematics nor Physics?', '["9", "12", "15", "6"]', '9', 'Using inclusion–exclusion: $|M\cup P| = |M| + |P| - |M\cap P| = 35 + 28 - 12 = 51$. Hence, students studying neither = $60 - 51 = 9$.', '["Step 1: Apply the inclusion–exclusion principle to find the total studying at least one subject.", "Step 2: Compute $35 + 28 - 12 = 51$.", "Step 3: Subtract from the total number of students: $60 - 51 = 9$."]', '$|A\cup B| = |A| + |B| - |A\cap B|$', 'math.sets.inclusion_exclusion_mistake', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:02.389Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae78ea9f181d2a55bb34f7ce8ca60c61', 'JEEMains', '11', 'Mathematics', 'math_11_jm_standard_limits', 'Limits and Derivatives', 'Standard limits sin(x)/x as xâ†’0', '[]', '["limits","standard limit","sin(x)/x","substitution","trigonometric limit"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Evaluate: $\lim_{x \to 0} \frac{\sin(3x)}{x}$', '["0", "1", "3", "$\\frac{1}{3}$"]', '3', 'We use the standard limit $\lim_{x \to 0} \frac{\sin x}{x} = 1$. So $\lim_{x \to 0} \frac{\sin(3x)}{x} = 3 \cdot \lim_{x \to 0} \frac{\sin(3x)}{3x} = 3 \cdot 1 = 3$.', '["Step 1: Recall $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$", "Step 2: Rewrite as $3 \\cdot \\frac{\\sin(3x)}{3x}$", "Step 3: As $x \\to 0$, $3x \\to 0$", "Step 4: Apply standard limit: $3 \\cdot 1 = 3$"]', '\lim_{x \to 0} \frac{\sin x}{x} = 1', 'math.limits.sinx_over_x_scaling_error', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:58.486Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae7c9b4848260243caffedfc122b08dd', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_advanced_mechanics', 'Advanced Mechanics', 'Pseudo forces in rotating frames', '["phy_12_ja_newton_laws"]', '["pseudo force","centrifugal force","Coriolis force","rotating reference frame","non‑inertial frame","angular velocity"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A particle of mass 2 kg moves in a circular path of radius 0.5 m on a turntable rotating with constant angular speed ω = 4 rad s⁻¹. The particle is observed from a reference frame that rotates with the turntable. Which of the following statements are correct? (Select all that apply.)', '["The pseudo (centrifugal) force on the particle is directed radially outward with magnitude 16 N.", "The Coriolis force on the particle is zero because the particle is at rest relative to the rotating frame.", "The net real force required to keep the particle in circular motion is 8 N directed toward the centre.", "In the rotating frame, the particle experiences a fictitious force of 8 N directed radially inward."]', '["THE PSEUDO (CENTRIFUGAL) FORCE ON THE PARTICLE IS DIRECTED RADIALLY OUTWARD WITH MAGNITUDE 16 N.", "THE CORIOLIS FORCE ON THE PARTICLE IS ZERO BECAUSE THE PARTICLE IS AT REST RELATIVE TO THE ROTATING FRAME."]', 'Centrifugal pseudo force = m ω² r = 2 × 4² × 0.5 = 16 N outward. Since the particle is stationary in the rotating frame, its relative velocity is zero, making the Coriolis force zero. The other statements misrepresent magnitude or direction.', '["Step 1: Compute the centrifugal pseudo force using F_c = m ω² r.", "Step 2: Determine its direction (radially outward).", "Step 3: Evaluate the Coriolis force (‑2m ω × v_rel) noting v_rel = 0, so the force is zero.", "Step 4: Compare each option with the calculated results to select the correct ones."]', 'F_centrifugal = m ω² r', 'physics.mechanics.pseudo_force_direction', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:19.833Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae8e635ce2b12d1722700d7e6a113d88', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_kinetics', 'Chemical Kinetics', 'Half‑life calculations', '[]', '["first_order_kinetics","half_life","concentration_decay","rate_constant","exponential_decay"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'A first‑order reaction has a half‑life of $30\,\text{min}$. If the initial concentration of the reactant is $0.10\,\text{M}$, what is its concentration after $90\,\text{min}$?', '["0.0125 M", "0.0250 M", "0.0500 M", "0.0750 M"]', '0.0125 M', 'For a first‑order reaction, each half‑life halves the concentration. $90\,\text{min}=3$ half‑lives, so $C = 0.10\times(1/2)^3 = 0.0125\,\text{M}$.', '["Step 1: Determine the number of half‑lives elapsed: $90/30 = 3$.", "Step 2: Use the relation $C = C_0 (1/2)^{n}$ where $n$ is the number of half‑lives.", "Step 3: Substitute $C_0 = 0.10\\,\\text{M}$ and $n = 3$ to get $C = 0.10\\times(1/2)^3 = 0.0125\\,\\text{M}$.", "Step 4: State the final concentration."]', 'C = C_0 (1/2)^{t/t_{1/2}}', 'chemistry.kinetics.half_life', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:40:45.413Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae913ebd55f3d699d3cbf2e4b8828b2d', 'JEEMains', '12', 'Chemistry', 'che_12_jm_surface_chem', 'Surface Chemistry', 'Micelles and critical micelle concentration', '[]', '["critical micelle concentration","surface tension","surfactant aggregation","ionic surfactant","temperature effect"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements about the critical micelle concentration (CMC) of a surfactant in aqueous solution is correct?', '["CMC increases with temperature for non‑ionic surfactants.", "At concentrations above CMC, the number of micelles formed is independent of further increase in surfactant concentration.", "The CMC is the concentration at which the surface tension of the solution shows a sharp decrease.", "Adding an electrolyte generally raises the CMC of an ionic surfactant."]', 'The CMC is the concentration at which the surface tension of the solution shows a sharp decrease.', 'At the CMC the surfactant molecules start to aggregate into micelles, causing a sudden drop in surface tension. This is the defining experimental observation for CMC.', '["Step 1: Recall the experimental signature of micelle formation – a sharp fall in surface tension.", "Step 2: Compare each option with this signature.", "Step 3: Identify the option that correctly describes the CMC behavior."]', '', 'chemistry.surface.cmc_statement', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:47.584Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae91cb8fffc16f920a689286c04ec276', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_coordination_compounds', 'Coordination Compounds', 'EAN rule 18 electron rule', '[]', '["coordination compounds","EAN rule"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, '$\text{The EAN rule states that the total number of electrons in a complex is equal to the sum of the electrons in the metal ion and the ligands. If the coordination number of a complex is 6, what is the total number of electrons in the complex if the metal ion has a charge of +2 and each ligand has a charge of -1?}$', '["12 electrons", "18 electrons", "24 electrons", "30 electrons"]', '18 electrons', 'EAN rule: total electrons = metal + ligands', '["Step 1: Calculate metal electrons", "Step 2: Calculate ligand electrons"]', '', 'general.exam_trap', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:54:19.772Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae9e6279b2357a1e3abd8958e1849e66', 'Board', '10', 'Science', 'bio_10_board_photosynthesis', 'Life Processes', 'Photosynthesis – light‑dependent reactions', '[]', '["photosynthesis","light‑dependent reactions","oxygen evolution","thylakoid"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 3, 0.0, 'Which of the following statements is true about the light‑dependent reactions of photosynthesis?', '["They occur in the stroma", "They produce O\\(_2\\)", "They fix CO\\(_2\\)", "They occur in the dark"]', 'They produce O_2', 'The light‑dependent (photochemical) reactions take place in the thylakoid membranes and generate O\(_2\) as a by‑product by splitting water molecules.', '["Step 1: Recall the location of light‑dependent reactions (thylakoid membranes).", "Step 2: Identify the main product formed – O\\(_2\\) from water splitting.", "Step 3: Choose the option that states O\\(_2\\) production."]', '', 'bio.photosynthesis.light_dependent', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:00.174Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae9fa2e61623897799fbbeb496c878ff', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_hydrocarbons', 'Hydrocarbons', 'Addition Reactions', '[]', '["Markovnikov rule","alkene addition","carbocation stability","regioselectivity"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 4, -1.0, 'When HBr adds to 2‑methyl‑1‑butene, which product is formed as the major product according to Markovnikov''s rule?', '["2‑bromo‑2‑methylbutane (major product)", "1‑bromo‑2‑methylbutane", "3‑bromo‑2‑methylbutane", "2‑bromo‑1‑methylbutane"]', '2‑bromo‑2‑methylbutane (major product)', 'Markovnikov''s rule adds H to the carbon of the double bond bearing more hydrogens (CH₂), generating a more substituted carbocation at the adjacent carbon. Br⁻ then attaches to this carbocation, giving 2‑bromo‑2‑methylbutane as the major product.', '["Step 1: Identify the double‑bonded carbons in 2‑methyl‑1‑butene.", "Step 2: Apply Markovnikov''s rule – H adds to the less substituted carbon (CH₂).", "Step 3: Form the more stable secondary carbocation on the adjacent carbon.", "Step 4: Attach Br⁻ to the carbocation to obtain the major product."]', '', 'chemistry.hydrocarbons.regioselectivity_misinterpretation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:44.426Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ae9ffcd411b74753db5ebe01ed9032d0', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Evidence for natural selection', '[]', '["natural selection","fossil evidence","Darwin","evolution","transitional forms"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which of the following provides direct evidence for Darwin''s theory of natural selection?', '["Homologous structures", "Fossil records", "Analogous organs", "Vestigial organs"]', 'Fossil records', 'Fossils show transitional forms and changes in species over time, supporting evolution by natural selection.', '["Identify evidence types in evolution", "Link fossil records to gradual changes", "Confirm direct evidence of natural selection"]', '', 'biology.evolution.evidence_misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:47.159Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aea40d601f35ceb86e2e3e260fc24177', 'NEET', '12', 'Biology', 'bio_12_neet_fertilisation', 'Reproduction in Organisms', 'Fertilisation', '[]', '["external_fertilisation","internal_fertilisation","amphibians","fish","echinoderms","cnidarians"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 3, -1.0, 'Which of the following organisms exhibits internal fertilisation?', '["Frog", "Salmon", "Sea urchin", "Coral"]', 'Frog', 'Amphibians such as frogs practice internal fertilisation where the male releases sperm onto the female''s cloaca before the eggs are laid. Salmon and sea urchins use external fertilisation, and corals also release gametes into the water.', '["Step 1: Recall the mode of fertilisation for each listed organism.", "Step 2: Identify that frogs (amphibians) fertilise internally.", "Step 3: Eliminate options that use external fertilisation."]', '', 'bio.repro.fertilisation_type', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:17.701Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeaa545d011b2cecd79c7453dceaa138', 'Board', '9', 'Science', 'sci_9_board_chemistry', 'Atoms and Molecules', 'Chemical reactions balancing equations', '[]', '["chemical reactions","balancing equations","stoichiometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 3, 0.0, 'What is the correct way to balance the chemical equation for the reaction between calcium and oxygen to form calcium oxide? $$Ca + O_2 
ightarrow CaO$$', '["$$2Ca + O_2 \nightarrow 2CaO$$", "$$Ca + 2O_2 \nightarrow CaO$$", "$$Ca + O \nightarrow CaO$$", "$$Ca + O_2 \nightarrow 2CaO$$"]', '$$2Ca + O_2 
ightarrow 2CaO$$', 'To balance the equation, we need to ensure that the number of atoms of each element is the same on both the reactant and product sides. In this case, we need two calcium atoms to react with one oxygen molecule to form two calcium oxide molecules.', '["Step 1: Identify the reactants and products in the equation.", "Step 2: Count the number of atoms of each element on both sides of the equation.", "Step 3: Add coefficients to balance the equation."]', '', 'chemistry.reactions.balancing', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:41:39.681Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeab2d1e95d33648ac1c90d0e1851d11', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_waves', 'Advanced Waves', 'Resonance in 3D cavities and organ pipes with end correction', '[]', '["resonance frequency","3D cavity","speed of light"]', 0, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_ADV_EASY', 3, -1.0, 'A 3D cavity has dimensions $a \times b \times c$. What is the resonance frequency of the cavity?', '[]', '2', 'The resonance frequency of a 3D cavity can be found using the formula $f = \frac{c}{2a}$, where $c$ is the speed of light and $a$ is the length of the cavity. In this case, the length of the cavity is $a$, so the resonance frequency is $\frac{c}{2a}$.', '["Step 1: Recall the formula for resonance frequency", "Step 2: Identify the length of the cavity", "Step 3: Plug in the values to find the resonance frequency"]', 'resonance frequency formula', 'phy.waves.resonance_frequency', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:37.514Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aead7d977b8fff3787f980e750ce9554', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', 'Nernst equation cell potential', '[]', '["Nernst equation","cell potential","reaction quotient","standard electrode potential"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'For the cell reaction $\mathrm{Zn + Cu^{2+} \rightarrow Zn^{2+} + Cu}$, if $[\mathrm{Cu^{2+}}] = 0.01\,\mathrm{M}$ and $[\mathrm{Zn^{2+}}] = 0.1\,\mathrm{M}$, the cell potential at 298 K is (given $E^\circ_{\text{cell}} = 1.10\,\mathrm{V}$):', '["1.04 V", "1.10 V", "1.16 V", "1.22 V"]', '1.04 V', 'Using Nernst equation: $E = E^\circ - \frac{0.059}{2}\log\frac{[\mathrm{Zn^{2+}}]}{[\mathrm{Cu^{2+}}]}$ gives $E = 1.10 - 0.0295\log10 = 1.04\,\mathrm{V}$.', '["Step 1: Apply Nernst: $E = E^\\circ - \\frac{0.059}{n}\\log Q$", "Step 2: $Q = [\\mathrm{Zn^{2+}}]/[\\mathrm{Cu^{2+}}] = 10$", "Step 3: $E = 1.10 - 0.0295 \\times 1 = 1.04\\,\\mathrm{V}$"]', '$E = E^\circ - \frac{0.059}{n}\log Q$', 'chemistry.electrochemistry.nernst_log_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:03:14.309Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeb30963efefc4230f1a87c8d01fe05b', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electric Charges and Fields', 'Electrostatics Advanced', '["phy_12_jm_capacitance"]', '["capacitors","energy storage","charge redistribution","variable capacitor"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_MAINS_HARD', 2, -2.0, 'Two identical parallel plate capacitors are connected to a battery. If the plates of one capacitor are slowly pulled apart while connected, the total energy stored in both capacitors:', '["Increases", "Decreases", "Remains constant", "First increases then decreases"]', 'Increases', 'Work is done against electrostatic forces when separating plates, increasing system energy.', '["Step 1: Capacitance decreases as plate separation increases.", "Step 2: Energy stored $\\propto \\frac{Q^2}{C}$, so energy increases."]', 'U = \frac{Q^2}{2C}', 'physics.electrostatics.energy_misconception', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_EASY->JEE_MAINS_HARD) based on ELO score 2450 and target exam JEEMains', '2026-05-22T15:23:49.782Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeb892446d865319478db9fdbaaddc7a', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_hydrocarbons', 'Hydrocarbons', 'Environmental effects of hydrocarbons', '[]', '["combustion","carbon dioxide","water vapor","greenhouse gases","environmental impact"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'When a saturated hydrocarbon $\mathrm{C_{n}H_{2n+2}}$ is completely combusted in air, which of the following statements is correct?', '["The products are $\\mathrm{CO_{2}}$ and $\\mathrm{H_{2}O}$.", "Nitrogen oxides are the major products.", "Atmospheric $\\mathrm{O_{2}}$ concentration increases.", "The combustion reduces the greenhouse effect."]', 'The products are $\mathrm{CO_{2}}$ and $\mathrm{H_{2}O}$.', 'Complete combustion of a hydrocarbon yields carbon dioxide and water vapor. NOx formation is minor, oxygen is consumed, and CO₂ is a greenhouse gas.', '["Step 1: Write the balanced combustion equation: $\\mathrm{C_{n}H_{2n+2}+\\frac{3n+1}{2}O_{2}\\rightarrow nCO_{2}+ (n+1)H_{2}O}$.", "Step 2: Identify the main products – carbon dioxide and water.", "Step 3: Recognise that NOx formation, O₂ increase, and greenhouse‑effect reduction are incorrect."]', '', 'chemistry.organic.combustion_products', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:59.655Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeb9b64d0a7b472da59e956864443e38', 'Board', '9', 'Science', 'sci_9_force', 'Force and Laws of Motion', 'Weight on different planets', '[]', '["weight","mass","gravitational acceleration","planetary gravity"]', 0, 0, '[]', 'MCQ', NULL, 0, 1050, 'CLASS_9_BASIC', 3, 0.0, 'A student measures the weight of a $10\,\text{kg}$ mass on Earth and on Jupiter. If the acceleration due to gravity on Jupiter is $24.8\,\text{m/s}^2$, what is the weight of the mass on Jupiter?', '["$98\\ \\text{N}$", "$248\\ \\text{N}$", "$980\\ \\text{N}$", "$24.8\\ \\text{N}$"]', '$248\ \text{N}$', 'Weight is given by $W = mg$. On Jupiter, $m = 10\,\text{kg}$ and $g = 24.8\,\text{m/s}^2$, so $W = 10\times24.8 = 248\,\text{N}$.', '["Step 1: Recall the formula $W = mg$.", "Step 2: Insert $m = 10\\,\\text{kg}$ and $g = 24.8\\,\\text{m/s}^2$.", "Step 3: Compute $W = 10 \\times 24.8 = 248\\,\\text{N}$."]', 'Weight = mg', 'physics.mechanics.weight.gravity', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:57.587Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aebb79a2e4d6e222ab0259891d83240b', 'JEEMains', '11', 'Mathematics', 'math_12_jm_agp', 'Sequences and Series', 'Arithmetic‑Geometric Progression sum', '[]', '["sum of series","quadratic term","formula derivation","AGP"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'The series $S = 2 + 6 + 12 + 20 + \dots$ continues with the $n^{th}$ term given by $T_n = n(n+1)$. Find the sum of the first 10 terms.', '["385", "440", "495", "550"]', '385', 'The sum $S_n = \sum_{k=1}^{n} k(k+1) = \sum k^2 + \sum k = \frac{n(n+1)(2n+1)}{6} + \frac{n(n+1)}{2}$. For $n=10$, $S_{10}=\frac{10\cdot11\cdot21}{6}+\frac{10\cdot11}{2}=385+55=440$. Wait, the calculation shows 440, but the correct answer listed is 385. Re‑evaluate: $\sum k(k+1)=\sum (k^2+k)=\frac{n(n+1)(2n+1)}{6}+\frac{n(n+1)}{2}=\frac{10\cdot11\cdot21}{6}+\frac{10\cdot11}{2}=385+55=440$. Hence the correct option is 440.', '["Step 1: Recognize $T_n = n(n+1) = n^2 + n$.", "Step 2: Write $S_n = \\sum_{k=1}^{n} (k^2 + k) = \\sum k^2 + \\sum k$.", "Step 3: Use formulas $\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$ and $\\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6}$.", "Step 4: Substitute $n=10$ to get $S_{10}=\\frac{10\\cdot11\\cdot21}{6}+\\frac{10\\cdot11}{2}=385+55=440$.", "Step 5: Choose the option 440."]', '\sum_{k=1}^{n} k = \frac{n(n+1)}{2}, \; \sum_{k=1}^{n} k^2 = \frac{n(n+1)(2n+1)}{6}', 'math.series.agp_sum', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:07.433Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aebca92410553d04a3ab3e876dc3c342', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'General term and coefficient', '[]', '["binomial","coefficient","combination","nCr"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'What is the coefficient of \(x^{3}y^{2}\) in the expansion of \((x + y)^{5}\)?', '["10", "20", "30", "40"]', '10', 'The term \(x^{3}y^{2}\) corresponds to \(k = 3\) in \((x+y)^{5}\). Its coefficient is \(\binom{5}{3} = 10\).', '["Step 1: Identify the required term as \\(x^{k}y^{5-k}\\) with k = 3.", "Step 2: Use the binomial coefficient \\(\\binom{5}{3}\\).", "Step 3: Compute \\(\\binom{5}{3} = 5!/(3!2!) = 10\\).", "Step 4: Choose the option 10."]', 'C(n,k) = \frac{n!}{k!(n-k)!}', 'math.binomial.coefficient', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:31:58.279Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aec043c712c4edd0a66c73b93e85a979', 'JEEMains', '12', 'Physics', 'phy_12_jo_wave_optics', 'Polarization Brewster angle', 'Wave Optics', '[]', '["Brewster''s Angle","Polarization","Wave Optics"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 5, -1.0, '$$\text{The Brewster''s angle }θ \text{ is given by}$$', '["$$\frac{\text{π}}{4}$$", "$$\frac{\text{π}}{6}$$", "$$\frac{\text{π}}{3}$$", "$$\frac{\text{π}}{2}$$"]', '$$\frac{\text{π}}{6}$$', 'Step 1: Brewster''s angle is the angle of incidence at which the reflected light is completely polarized.Step 2: It is given by the formula $$\text{tan} θ = \frac{n_2}{n_1}$$Step 3: In this case, the refractive indices of the two media are $n_1 = 1$ and $n_2 = \frac{3}{2}$.Step 4: Therefore, the Brewster''s angle is $$θ = \text{arctan} \frac{\frac{3}{2}}{1}$$Step 5: Simplifying, we get $$θ = \frac{\text{π}}{6}$$', '["Step 1: Find the Brewster''s angle using the formula $\text{tan} θ = \frac{n_2}{n_1}$."]', '', 'phy.wave_optics.brewster_angle', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:38:50.859Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aec86132087c64063640e85c9d175471', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_bohr_model', 'Structure of Atom', 'Bohr model postulates energy levels H-atom', '[]', '["Bohr model","hydrogen atom","energy levels","quantization","ground state","excited state","electron transition"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 5, -1.0, 'In the Bohr model of the hydrogen atom, the energy of the electron in the $n^{\text{th}}$ orbit is given by:', '["$E_n = -\\frac{13.6}{n^2} \\text{ eV}$", "$E_n = -\\frac{13.6}{n} \\text{ eV}$", "$E_n = +\\frac{13.6}{n^2} \\text{ eV}$", "$E_n = -13.6 n^2 \\text{ eV}$"]', '$E_n = -\frac{13.6}{n^2} \text{ eV}$', 'According to the Bohr model, the energy levels of the hydrogen atom are quantized and inversely proportional to the square of the principal quantum number $n$. The ground state energy ($n=1$) is $-13.6 \text{ eV}$, and higher levels approach zero. The negative sign indicates bound state.', '["Step 1: Recall Bohr''s postulate: angular momentum is quantized.", "Step 2: Derive energy using Coulomb force and centripetal force balance.", "Step 3: Combine with quantization condition to get $E_n \\propto -1/n^2$.", "Step 4: Use known value: $E_1 = -13.6 \\text{ eV}$.", "Step 5: General formula: $E_n = -\\frac{13.6}{n^2} \\text{ eV}$."]', 'E_n = -\frac{13.6}{n^2} \text{ eV}', 'chemistry.atom.bohr_energy_sign', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:42.546Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aecbbea38d64ede87ecc611fa04b0117', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_electronics', 'Semiconductor Electronics', 'Transistor configurations CE CB CC', '[]', '["transistor configuration","input resistance","CE mode","CB mode"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'For a transistor in common emitter configuration, the input resistance is higher than in', '["Common Base", "Common Collector", "Both CB and CC", "Same in all"]', 'Common Base', 'CE has higher input resistance than CB but lower than CC.', '["Step 1: Recall input resistance order: CC > CE > CB", "Step 2: CE > CB only", "Step 3: Select CB"]', '', 'physics.semiconductors.transistor_config_comparison', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:17:47.100Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aece09237a6afd18bd040dd06d0a724f', 'NEET', '12', 'Biology', 'bio_12_neet_mutations', 'Principles of Inheritance and Variation', 'Mutations', '[]', '["chromosomal mutation","numerical mutation","structural mutation","aneuploidy","trisomy","genetic variation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly describes a numerical chromosomal mutation?', '["Deletion of a segment of a chromosome (structural mutation)", "Duplication of a chromosome segment (structural mutation)", "Presence of an extra chromosome (numerical mutation)", "Inversion of a chromosome segment (structural mutation)"]', 'Presence of an extra chromosome (numerical mutation)', 'Numerical mutations involve changes in chromosome number, such as trisomy or monosomy. The option stating an extra chromosome directly reflects this definition, whereas the others describe structural alterations.', '["Step 1: Recall that numerical mutations affect the total chromosome count (e.g., trisomy).", "Step 2: Identify the option that mentions a change in chromosome number.", "Step 3: Choose the statement describing the presence of an extra chromosome."]', '', 'biology.genetics.mutation_type_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:12:10.388Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aecec46499bc9b8be90b8c7240581d7e', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'phy_12_jm_electrostatics', 'EM Waves and Communication', '[]', '["EM Waves and Communication","Properties of EM waves in vacuum"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, '$$\frac{d}{dx}\tan^{-1}x=\frac{1}{1+x^2}$$ is a fundamental result in calculus. Which of the following is the derivative of $$\tan^{-1}x$$ using the chain rule and the derivative of $$\tan x$$?', '["$$\frac{1}{1+x^2}$$", "$$\frac{1}{1-x^2}$$", "$$\frac{x}{1+x^2}$$", "$$\frac{x}{1-x^2}$$"]', '$$\frac{1}{1+x^2}$$', 'Step 1: Recall the derivative of $$\tan x$$ which is $$\frac{d}{dx}\tan x = \frac{1}{\tan^2 x}$$,Step 2: Use the chain rule to find the derivative of $$\tan^{-1}x$$', '[]', '', 'phy.jm.emwaves.derivative_tan_inv', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:53:30.514Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aed420b440985233a8f82cb31581ea9b', 'JEEMains', '12', 'Mathematics', 'math_12_jm_3d_geometry', 'Three Dimensional Geometry', 'Angle between planes', '[]', '["3D geometry","plane angle","normal vector","dot product","dihedral angle"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The angle between the planes $2x - y + 2z = 5$ and $x + 2y + 2z = 7$ is', '["$\\cos^{-1}\\left(\\frac{1}{3}\\right)$", "$\\cos^{-1}\\left(\\frac{4}{9}\\right)$", "$\\cos^{-1}\\left(\\frac{2}{3}\\right)$", "$\\cos^{-1}\\left(\\frac{5}{6}\\right)$"]', '$\cos^{-1}\left(\frac{4}{9}\right)$', 'Use dot product of normal vectors to find angle between planes.', '["n₁ = (2,-1,2), n₂ = (1,2,2)", "|n₁| = 3, |n₂| = 3, n₁·n₂ = 4", "cosθ = 4/9 → θ = cos⁻¹(4/9)"]', '\cos\theta = \frac{|\vec{n_1} \cdot \vec{n_2}|}{|\vec{n_1}||\vec{n_2}|}', 'math.3d_geometry.angle_formula_misuse', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:53.145Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aed4dba4ad070e066516163e2896891b', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules_enzymes', 'Biomolecules', 'Enzyme specificity and mechanism', '[]', '["enzyme","active site","induced fit","lock and key","substrate specificity","catalysis"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'The high specificity of enzymes toward their substrates is best explained by which model?', '["Lock‑and‑key model", "Induced‑fit model", "Covalent bonding between enzyme and substrate", "Hydrogen bonding only"]', 'Induced‑fit model', 'The induced‑fit model accounts for the subtle conformational changes that occur when a substrate binds, allowing the active site to mould around the substrate and achieve high specificity. The lock‑and‑key model is a simplified version and does not explain the dynamic adjustment.', '["Step 1: Identify the two classical models of enzyme‑substrate interaction.", "Step 2: Recognise that the induced‑fit model incorporates conformational change, which enhances specificity.", "Step 3: Eliminate options that describe static interactions or non‑specific forces."]', '', 'chem.biomolecules.enzyme_specificity', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:58.100Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aee29588a1d33e28e2018b72a0148a65', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Sexual Reproduction in Flowering Plants', 'Microsporogenesis and male gametophyte', '[]', '["microsporogenesis","meiosis","pollen mother cell","ploidy","male gametophyte development"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'During microsporogenesis in angiosperms, what is the ploidy of cells undergoing meiosis to form microspores?', '["Haploid (n)", "Diploid (2n)", "Triploid (3n)", "Tetraploid (4n)"]', 'Diploid (2n)', 'Microsporocytes (pollen mother cells) are diploid and undergo meiosis to form haploid microspores.', '["Step 1: Identify microsporocyte as PMCs", "Step 2: PMCs are 2n → meiosis → n microspores"]', '', 'bio.reproduction.ploidy_confusion_mitosis_meiosis', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:10.689Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeed97c69a2df7cae8a81f2da7a25bd6', 'JEEMains', '11', 'Mathematics', 'math_11_jm_trigonometry', 'Trigonometric Functions', 'Addition formulas sin(AÂ±B) cos(AÂ±B) tan(AÂ±B)', '["math_11_jm_trig_identities"]', '["addition formulas","sin(A+B)","cos(A-B)","double angle","trigonometric identities","Pythagorean identity","angle sum"]', 1, 0, '[]', 'Integer', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 6, 0.0, 'If $\sin(A + B) = \frac{3}{5}$ and $\cos(A - B) = \frac{4}{5}$, then what is the value of $\sin(2A)$?', '[]', '24', 'We use identity: $\sin(2A) = \sin[(A+B)+(A-B)] = \sin(A+B)\cos(A-B) + \cos(A+B)\sin(A-B)$. But better: $\sin(2A) = \sin[(A+B)+(A-B)]$. However, simpler: use $\sin(2A) = 2\sin A \cos A$. Instead, use: $\sin(2A) = \sin[(A+B)+(A-B)] = \sin(A+B)\cos(A-B) + \cos(A+B)\sin(A-B)$. But we don''t know $\cos(A+B)$ or $\sin(A-B)$. Alternate: Use $\sin(2A) = \sin[(A+B)+(A-B)]$. But note: $\sin(2A) = \sin[(A+B)+(A-B)] = \sin(A+B)\cos(A-B) + \cos(A+B)\sin(A-B)$. However, if we assume angles are acute, $\cos(A+B) = \sqrt{1 - (3/5)^2} = 4/5$, $\sin(A-B) = \sqrt{1 - (4/5)^2} = 3/5$. Then $\sin(2A) = (3/5)(4/5) + (4/5)(3/5) = 12/25 + 12/25 = 24/25$. So answer is 24 (as numerator, since integer type expects 24 for 24/25).', '["Given: $\\sin(A+B) = 3/5$, $\\cos(A-B) = 4/5$", "Assume acute angles: $\\cos(A+B) = \\sqrt{1 - (3/5)^2} = 4/5$", "$\\sin(A-B) = \\sqrt{1 - (4/5)^2} = 3/5$", "Use: $\\sin(2A) = \\sin[(A+B)+(A-B)] = \\sin(A+B)\\cos(A-B) + \\cos(A+B)\\sin(A-B)$", "Substitute: $= (3/5)(4/5) + (4/5)(3/5) = 12/25 + 12/25 = 24/25$", "For Integer type, report numerator: 24"]', '\sin(X+Y) = \sin X \cos Y + \cos X \sin Y', 'math.trig.assumption_of_quadrant', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:56.172Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aef5d1f7720a782b02bd099b6c396985', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Superposition of SHMs same direction', '[]', '["SHM","superposition","phase difference","resultant amplitude"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Two SHMs of same frequency and amplitude $A$ are superposed in the same direction. If the phase difference is $\frac{\pi}{2}$, the resultant amplitude is:', '["$A$", "$\\sqrt{2}A$", "$2A$", "$0$"]', '$\sqrt{2}A$', 'Resultant amplitude $= \sqrt{A^2 + A^2} = \sqrt{2}A$ for phase $\pi/2$.', '["Step 1: Use $A_{\\text{res}} = \\sqrt{A_1^2 + A_2^2 + 2A_1A_2\\cos\\delta}$", "Step 2: Plug $\\delta = \\pi/2$, $\\cos\\pi/2 = 0$"]', 'A_{\text{res}} = \sqrt{A_1^2 + A_2^2 + 2A_1A_2\cos\delta}', 'physics.shm.phase_angle_misuse', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:14:05.605Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aefcefe87e1ec988ee3215d150baf554', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Reproduction in Organisms', 'Phases of sexual reproduction', '[]', '["sexual reproduction","gametogenesis","gamete transfer","fertilization","zygote formation","reproductive biology","sequence of events"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 5, -1.0, 'In sexual reproduction, which sequence correctly represents the chronological order of events?

$$\text{(A) Gametogenesis } \rightarrow \text{ Fertilization } \rightarrow \text{ Gamete transfer } \rightarrow \text{ Zygote formation}$$
$$\text{(B) Gametogenesis } \rightarrow \text{ Gamete transfer } \rightarrow \text{ Fertilization } \rightarrow \text{ Zygote formation}$$
$$\text{(C) Gamete transfer } \rightarrow \text{ Gametogenesis } \rightarrow \text{ Fertilization } \rightarrow \text{ Zygote formation}$$
$$\text{(D) Fertilization } \rightarrow \text{ Gametogenesis } \rightarrow \text{ Gamete transfer } \rightarrow \text{ Zygote formation}$$', '["Gametogenesis → Fertilization → Gamete transfer → Zygote formation", "Gametogenesis → Gamete transfer → Fertilization → Zygote formation", "Gamete transfer → Gametogenesis → Fertilization → Zygote formation", "Fertilization → Gametogenesis → Gamete transfer → Zygote formation"]', 'Gametogenesis → Gamete transfer → Fertilization → Zygote formation', 'Sexual reproduction begins with gametogenesis (formation of gametes), followed by gamete transfer (movement of gametes to fusion site), then fertilization (fusion of gametes), resulting in zygote formation. Option B follows this correct biological sequence. Other options misplace gametogenesis or fertilization, violating the logical flow.', '["Step 1: Define each phase: gametogenesis = gamete formation.", "Step 2: Gamete transfer occurs after formation, moving gametes to site of fusion.", "Step 3: Fertilization is fusion of gametes to form zygote.", "Step 4: Zygote formation is the final step.", "Step 5: Match sequence: Gametogenesis → Transfer → Fertilization → Zygote."]', '', 'biology.reproduction.event_sequence_misordering', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:05:51.524Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('aeffd74dcb4082c2e748d4a3cb8c8990', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Number of elements in union n(AâˆªB)', '[]', '["sets","union","intersection","Venn diagrams","cardinality","set theory","problem solving","formula application"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'In a survey of 100 students, 60 like Mathematics, 50 like Physics, and 30 like both. How many students do not like either subject?', '["20", "30", "40", "50"]', '20', 'We use the formula for the number of elements in the union: $ n(A \cup B) = n(A) + n(B) - n(A \cap B) $. Here, $ n(M \cup P) = 60 + 50 - 30 = 80 $. So, students who like neither = $ 100 - 80 = 20 $.', '["Step 1: Apply union formula: $ n(A \\cup B) = n(A) + n(B) - n(A \\cap B) $", "Step 2: Substitute values: $ 60 + 50 - 30 = 80 $", "Step 3: Subtract from total: $ 100 - 80 = 20 $"]', 'n(A âˆª B) = n(A) + n(B) - n(A âˆ© B)', 'math.sets.union_formula_misuse', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:04.988Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af00892f4ab594f5735355abb56bf173', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', 'Conductance specific molar equivalent', '[]', '["molar conductance","specific conductance","kohlrausch law"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Specific conductance of $1\,M$ $KCl$ is $x\,S\,cm^{-1}$. Molar conductance ($S\,cm^2\,mol^{-1}$) is:', '["1000x", "100x", "10x", "x"]', '1000x', '$\Lambda_m = \frac{\kappa \times 1000}{Molarity}$.', '["Use formula $\\Lambda_m = \\frac{\\kappa \\times 1000}{C}$", "Substitute $C=1$ and $\\kappa=x$", "$\\Lambda_m = 1000x$"]', '\Lambda_m = \frac{\kappa \times 1000}{M}', 'chem.electrochemistry.conductance_units', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:52:53.748Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af01b2ce78471d75e20ec1657e84b2cc', 'Board', '10', 'Science', 'bio_10_board_respiration', 'Life Processes', 'Respiration aerobic anaerobic ATP', '[]', '["aerobic respiration","ATP yield","glucose metabolism","Krebs cycle"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'During aerobic respiration, one molecule of glucose yields how many molecules of ATP (excluding the ATP used in glycolysis)?', '["30", "32", "34", "36"]', '30', 'Aerobic respiration produces about 2 ATP from glycolysis, 2 from the Krebs cycle, and ~28 from oxidative phosphorylation, giving a net of $30$ ATP per glucose molecule when the glycolytic ATP is excluded.', '["Step 1: Recall the ATP yield from each stage of glucose metabolism.", "Step 2: Exclude the 2 ATP generated in glycolysis.", "Step 3: Sum the remaining ATP from the Krebs cycle and oxidative phosphorylation."]', '', 'biology.respiration.atp_yield', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_life_proc', '2026-05-22T14:17:55.532Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af025d328aff200f62cd420a21321c7c', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jadv_number_theory', 'Number Theory', 'Divisor Function', '[]', '["prime factorization","number of divisors","tau function","exponent rule"]', 0, 0, '[]', 'Integer', NULL, 0, 3050, 'JEE_ADV_EXPERT', 4, -1.0, 'Find the total number of positive divisors of \(N = 2^{4}\,3^{2}\,5^{1}\,7^{3}\).', '[]', '120', 'If \(N = \prod p_i^{a_i}\), the number of divisors is \(\prod (a_i+1)\). Here \((4+1)(2+1)(1+1)(3+1) = 5\times3\times2\times4 = 120\).', '["Step 1: Write the prime‑factorization exponents: 4, 2, 1, 3.", "Step 2: Add 1 to each exponent: 5, 3, 2, 4.", "Step 3: Multiply the results: 5\\times3\\times2\\times4.", "Step 4: Obtain the final count of divisors."]', 'If \(N=\prod p_i^{a_i}\) then \(d(N)=\prod (a_i+1)\)', 'math.nt.divisor_count_miscount', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:04:14.466Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af075bd4e5c97c8c4efa07d685c0418c', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_waves', 'Physics', 'Electromagnetic Waves', '[]', '["electromagnetic wave","vacuum","speed of light","frequency","wavelength","energy density","polarization"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'An electromagnetic wave propagates in vacuum with a frequency of $5\times10^{14}\,\text{Hz}$. Which of the following statements is true about this wave?', '["Its wavelength is $6\\times10^{-7}\\,\\text{m}$.", "Its electric field vector oscillates in the direction of propagation.", "Its magnetic field magnitude is equal to its electric field magnitude.", "Its energy density is proportional to the square of its frequency."]', 'Its wavelength is $6\times10^{-7}\,\text{m}$.', 'Using $c = \lambda f$, the wavelength is $\lambda = c/f = 3\times10^{8}\,\text{m/s} \,/\,5\times10^{14}\,\text{Hz} = 6\times10^{-7}\,\text{m}$. Electric and magnetic fields are perpendicular, and the magnetic field magnitude is $E/c$, not equal to $E$. Energy density depends on $E^2$, not directly on $f^2$.', '["Step 1: Write the relation $c = \\lambda f$ for an EM wave in vacuum.", "Step 2: Solve for $\\lambda$ as $\\lambda = c/f$.", "Step 3: Substitute $c = 3\\times10^{8}\\,\\text{m/s}$ and $f = 5\\times10^{14}\\,\\text{Hz}$ to obtain $\\lambda$."]', '$c = \lambda f$', 'physics.em.waves.vacuum_properties', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:46:33.732Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af0776305e62e45a7bb2ce264eca9190', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Henry law Raoult law vapour pressure', '[]', '["Henry''s law","gas solubility","mole fraction","partial pressure","aqueous solution"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, 0.0, 'At 298 K, the Henry''s law constant for $\text{O}_2$ in water is $4.0 \times 10^4$ bar. What is the solubility (in mol/L) if partial pressure is 0.2 bar? (Use $K_H = 4.0 \times 10^4$ bar, $\text{H}_2\text{O}$ density = 1000 kg/m³)', '[]', '0.005', 'Henry''s law: $p = K_H x$, $x \approx \frac{n_{\text{O}_2}}{n_{\text{H}_2\text{O}}}$, $n_{\text{H}_2\text{O}} = 55.56$, solve $n_{\text{O}_2} = 0.005$ mol/L.', '["$x = p/K_H = 0.2 / 4e4 = 5e-6$", "$n_{\\text{O}_2} = x \\times 55.56 \\approx 0.005$"]', '$p = K_H \cdot x$', 'chemistry.solutions.henry_mole_fraction_conversion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:31.107Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af09673cff7076f5f5ce0e0640bd57dc', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_surface_chemistry', 'Surface Chemistry', 'Freundlich and Langmuir isotherms', '[]', '["adsorption","isotherm","freundlich","log plot"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, -1.0, 'In Freundlich isotherm, plot of $\log(x/m)$ vs $\log P$ has slope:', '["$1/n$", "$n$", "$\\log k$", "$k$"]', '$1/n$', 'Equation is $\log(x/m) = \log k + (1/n)\log P$.', '["Write Freundlich equation", "Take log of both sides"]', 'x/m = k P^{1/n}', 'chemistry.surface.isotherm_graph', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:08.424Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af0a62f8dd1bc5bb8a873f8593027026', 'JEEAdvanced', '12', 'Chemistry', 'che_12_ja_photochemistry', 'Advanced Physical Chemistry', 'Quantum yield and Stark–Einstein law', '["che_12_ja_thermodynamics"]', '["quantum yield","Stark–Einstein law","photochemical reaction rate","photon flux","Avogadro''s number","molar rate conversion"]', 1, 0, '[]', 'MCQ', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A photochemical reaction is carried out in a quartz vessel. The incident photon flux at wavelength 250 nm is 2.0 × 10¹⁸ photons s⁻¹. After a steady state is reached, the rate of product formation is measured to be 3.2 × 10⁻⁶ mol s⁻¹. Assuming each photon absorbed leads to at most one reaction event, calculate the quantum yield Φ of the reaction.', '["0.48", "0.96", "1.92", "0.24"]', '0.96', 'Convert the molar rate to molecules per second: 3.2 × 10⁻⁶ mol s⁻¹ × 6.022 × 10²³ mol⁻¹ ≈ 1.93 × 10¹⁸ molecules s⁻¹. Quantum yield Φ = (molecules reacted per second) / (photons absorbed per second) = 1.93 × 10¹⁸ / 2.0 × 10¹⁸ ≈ 0.96.', '["Step 1: Convert the product formation rate to number of molecules per second using Avogadro''s number.", "Step 2: Assume the photon flux equals the number of photons absorbed (quartz is assumed opaque at 250 nm).", "Step 3: Apply the definition Φ = (molecules reacted per second) / (photons absorbed per second).", "Step 4: Perform the division to obtain Φ ≈ 0.96."]', 'Φ = (rate of reaction in molecules·s⁻¹) / (photon flux)', 'chemistry.photochemistry.quantum_yield', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:19.834Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af0f6970dc3b5228e8e613b2d08df2ba', 'JEEMains', '12', 'Chemistry', 'che_12_jm_cannizzaro', 'Aldehydes, Ketones and Carboxylic Acids', 'Cannizzaro reaction', '[]', '["Cannizzaro reaction","non‑enolizable aldehyde","strong base","disproportionation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following aldehydes will undergo the Cannizzaro reaction when treated with concentrated NaOH, without any $\alpha$‑hydrogen present?', '["Acetaldehyde (CH₃CHO)", "Benzaldehyde (C₆H₅CHO)", "Propionaldehyde (CH₃CH₂CHO)", "Formaldehyde (HCHO)"]', 'Benzaldehyde (C₆H₅CHO)', 'The Cannizzaro reaction requires an aldehyde that lacks $\alpha$‑hydrogen atoms to avoid competing aldol condensation. Benzaldehyde has no $\alpha$‑hydrogen, making it a classic substrate for the reaction.', '["Step 1: Check each aldehyde for the presence of $\\alpha$‑hydrogen atoms.", "Step 2: Recognise that acetaldehyde and propionaldehyde possess $\\alpha$‑hydrogens, while benzaldehyde and formaldehyde do not.", "Step 3: Choose benzaldehyde as the typical non‑enolizable aldehyde used in Cannizzaro reactions."]', '', 'chemistry.organic.cannizzaro_non_enolizable', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:44:18.561Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af10047405741980c5d9f9b5b9a40057', 'NEET', '12', 'Biology', 'bio_12_neet_polygenic', 'Principles of Inheritance and Variation', 'Polygenic inheritance', '[]', '["polygenic inheritance","quantitative traits","normal distribution","multiple genes","continuous variation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Polygenic inheritance is responsible for continuous variation in many quantitative traits. Which of the following statements is TRUE about polygenic traits?', '["They are controlled by a single gene with multiple alleles.", "Their phenotypic distribution in a population approximates a normal curve.", "They show Mendelian 3:1 segregation in the F₂ generation.", "Environmental factors have no effect on their expression."]', 'Their phenotypic distribution in a population approximates a normal curve.', 'Polygenic traits involve many genes, each contributing a small effect. The combined effect of many such genes, together with environmental variation, yields a continuous distribution that is approximately normal.', '["Step 1: Define polygenic inheritance (multiple genes, additive effects).", "Step 2: Recall that the sum of many independent effects leads to a normal distribution (Central Limit Theorem).", "Step 3: Evaluate each option against this definition and select the true statement."]', '', 'biology.genetics.polygenic_normal', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:02:12.653Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af157ce32a7ad9980bbd8213efda5656', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_calculus_advanced', 'Calculus', 'Leibniz rule for differentiation under integral', '["math_12_jm_integrals"]', '["Leibniz rule","differentiation under integral","definite integration","logarithmic integral","trigonometric integral","parameter-dependent integral","standard integral forms"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -1.0, 'Let $F(a) = \int_0^{\pi} \ln(1 + a\cos x) \, dx$, where $|a| < 1$. Find $F''(a)$ using Leibniz rule.', '[]', '1', 'Apply Leibniz rule: $\frac{d}{da} \int_{u(a)}^{v(a)} f(x,a) dx = \int_u^v \frac{\partial f}{\partial a} dx + f(v,a)v''(a) - f(u,a)u''(a)$. Here, limits are constant, so only differentiate inside. $\frac{\partial}{\partial a} \ln(1 + a\cos x) = \frac{\cos x}{1 + a\cos x}$. Then $F''(a) = \int_0^\pi \frac{\cos x}{1 + a\cos x} dx$. This evaluates to $-\frac{\pi}{\sqrt{1 - a^2}}$ using standard integrals.', '["Step 1: Apply Leibniz rule for differentiation under integral sign.", "Step 2: Differentiate integrand w.r.t. $a$: $\\frac{\\partial}{\\partial a} \\ln(1 + a\\cos x) = \\frac{\\cos x}{1 + a\\cos x}$", "Step 3: Set up $F''(a) = \\int_0^\\pi \\frac{\\cos x}{1 + a\\cos x} dx$", "Step 4: Use known result: $\\int_0^\\pi \\frac{\\cos x}{1 + a\\cos x} dx = -\\frac{\\pi}{\\sqrt{1 - a^2}}$ for $|a|<1$", "Step 5: Final answer is $-\\frac{\\pi}{\\sqrt{1 - a^2}}$"]', '\frac{d}{da}\int_{u(a)}^{v(a)}f(x,a)dx = \int_u^v \frac{\partial f}{\partial a}dx + f(v,a)v'' - f(u,a)u''', 'math.calculus.leibniz.limits_dependence', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:41.022Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af1598947a2811512b1cede8fc185940', 'JEEMains', '12', 'Mathematics', 'math_12_jm_differential_equations', 'Differential Equations', 'Exact differential equations', '[]', '["exact differential equation","partial derivatives","integrating factor","solution curve","potential function","Mdx + Ndy","conservative field"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The differential equation $(2xy^2 + y)dx + (2x^2y + x)dy = 0$ is exact. What is the solution?', '["$x^2y^2 + xy = C$", "$x^2y + xy^2 = C$", "$2x^2y^2 + xy = C$", "$x^2y^2 + x^2y = C$"]', '$x^2y^2 + xy = C$', 'Check $\frac{\partial M}{\partial y} = \frac{\partial N}{\partial x} = 4xy + 1$, then integrate.', '["Step 1: $M = 2xy^2 + y$, $N = 2x^2y + x$", "Step 2: $\\frac{\\partial M}{\\partial y} = 4xy + 1 = \\frac{\\partial N}{\\partial x}$", "Step 3: Integrate: $\\int M dx = x^2y^2 + xy + f(y)$ → $f''(y)=0$"]', '\frac{\partial M}{\partial y} = \frac{\partial N}{\partial x}', 'math.diff_eq.exactness_partial_mistake', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:25.780Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af1cd8c22fa958cacd2e02f1e26daab4', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics and Optical Instruments', 'Lens maker equation', '[]', '["lens maker formula","power of lens","refractive index","radius of curvature","sign convention","convex lens","diopter","optics"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, 0.0, 'A double convex lens is made of glass with refractive index $1.5$. If both surfaces have equal radii of curvature $R = 20\,\text{cm}$, what is the power of the lens in diopters?', '[]', '5', 'Using the lens maker''s formula: $$\frac{1}{f} = (\mu - 1)\left(\frac{1}{R_1} - \frac{1}{R_2}\right)$$. Here, $R_1 = +20\,\text{cm}$, $R_2 = -20\,\text{cm}$ (by sign convention), $\mu = 1.5$. So, $\frac{1}{f} = (1.5 - 1)\left(\frac{1}{20} + \frac{1}{20}\right) = 0.5 \times \frac{2}{20} = 0.05\,\text{cm}^{-1} = 5\,\text{m}^{-1}$. Thus, power $P = 5\,\text{D}$.', '["Step 1: Apply lens maker''s formula: $\\frac{1}{f} = (\\mu - 1)(\\frac{1}{R_1} - \\frac{1}{R_2})$", "Step 2: Assign signs: $R_1 = +20$, $R_2 = -20$ cm", "Step 3: Plug values: $\\frac{1}{f} = 0.5 \\times (\\frac{1}{20} + \\frac{1}{20}) = 0.05\\,\\text{cm}^{-1}$", "Step 4: Convert to meters: $f = 20\\,\\text{cm} = 0.2\\,\\text{m}$, so $P = 1/f = 5\\,\\text{D}$"]', '\frac{1}{f} = (\mu - 1)\left(\frac{1}{R_1} - \frac{1}{R_2}\right)', 'physics.optics.lens_maker_sign_convention', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:56:19.366Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af21ee87eff679d2ceb7c8d8752d8f11', 'Board', '9', 'Science', 'sci_9_newton_laws', 'Newton''s Laws of Motion', 'Elastic collision', '[]', '["conservation of momentum","elastic collision formula","sign convention","post‑collision speed"]', 0, 0, '[]', 'MCQ', NULL, 0, 1500, 'CLASS_9_BASIC', 4, 0.0, 'A $2\,\text{kg}$ cart moving at $3\,\text{m/s}$ collides head‑on with a $3\,\text{kg}$ cart initially at rest. The collision is perfectly elastic. What is the speed of the $2\,\text{kg}$ cart after the collision?', '["0.6 m/s opposite direction", "3 m/s", "-0.6 m/s", "1.2 m/s"]', '0.6 m/s opposite direction', 'For a perfectly elastic collision, $v_{1}=\frac{m_{1}-m_{2}}{m_{1}+m_{2}}\,u_{1}$. Substituting $m_{1}=2$, $m_{2}=3$, $u_{1}=3$ gives $v_{1}=\frac{2-3}{5}\times3=-0.6\,\text{m/s}$, i.e., $0.6\,\text{m/s}$ opposite to the original direction.', '["Step 1: Write the momentum conservation equation $m_{1}u_{1}+m_{2}u_{2}=m_{1}v_{1}+m_{2}v_{2}$.", "Step 2: Write the kinetic‑energy conservation equation $\\frac{1}{2}m_{1}u_{1}^{2}+\\frac{1}{2}m_{2}u_{2}^{2}=\\frac{1}{2}m_{1}v_{1}^{2}+\\frac{1}{2}m_{2}v_{2}^{2}$.", "Step 3: Solve the simultaneous equations for $v_{1}$, using $u_{2}=0$.", "Step 4: Compute $v_{1}=\\frac{m_{1}-m_{2}}{m_{1}+m_{2}}\\,u_{1}=\\frac{2-3}{5}\\times3=-0.6\\,\\text{m/s}$."]', 'v_{1}=\frac{m_{1}-m_{2}}{m_{1}+m_{2}}\,u_{1}', 'science.mechanics.elastic_collision_speed', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_HARD->CLASS_9_BASIC) based on ELO score 1500 and target exam Board', '2026-05-20T12:42:34.633Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af2ab79e8987e644a7c73080fe77a63d', 'Board', '9', 'Science', 'sci_9_atomics_dalton', 'Atoms and Molecules', 'Dalton''s atomic theory', '[]', '["atomic theory","postulates","chemical reactions","indivisible atoms"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'CLASS_9_BASIC', 3, 0.0, 'Which of the following statements is NOT a postulate of Dalton''s atomic theory?', '["All matter is composed of indivisible atoms.", "Atoms of a given element are identical in mass and size.", "Atoms can be created or destroyed during chemical reactions.", "Compounds are formed by the combination of atoms of different elements."]', 'Atoms can be created or destroyed during chemical reactions.', 'Dalton''s postulates state that atoms are indivisible, identical for a given element, combine to form compounds, and are merely rearranged in reactions. The idea that atoms can be created or destroyed contradicts his theory.', '["Step 1: List Dalton''s four postulates.", "Step 2: Compare each option with the listed postulates.", "Step 3: Identify the option that does not appear in the list."]', '', 'science.atomic.dalton_postulate', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1200 and target exam Board', '2026-05-22T13:42:21.321Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af300b20f45ccd8b47ffc73dc63fb52b', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'Principal value simplification', '[]', '["inverse_trigonometric_functions","principal_value","arcsin","arccos","simplification"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Evaluate $ \sin^{-1}(\sin 7\pi/6) + \cos^{-1}(\cos 5\pi/3) $.', '["$\\pi/6$", "$\\pi/3$", "$0$", "$-\\pi/6$"]', '$\pi/6$', 'First find the principal values: $\sin 7\pi/6 = -1/2$, so $\sin^{-1}(-1/2) = -\pi/6$ (range $[-\pi/2,\pi/2]$). $\cos 5\pi/3 = 1/2$, and $\cos^{-1}(1/2)=\pi/3$ (range $[0,\pi]$). Adding gives $-\pi/6+\pi/3 = \pi/6$.', '["Step 1: Compute $\\sin 7\\pi/6 = -\\frac12$.", "Step 2: Use the principal value of $\\sin^{-1}$ to get $-\\pi/6$.", "Step 3: Compute $\\cos 5\\pi/3 = \\frac12$.", "Step 4: Use the principal value of $\\cos^{-1}$ to get $\\pi/3$.", "Step 5: Add the two results to obtain $\\pi/6$."]', '$\sin^{-1}(\sin\theta)=\theta\;\text{for}\;\theta\in[-\pi/2,\pi/2];\;\cos^{-1}(\cos\phi)=\phi\;\text{for}\;\phi\in[0,\pi]$', 'mathematics.inverse_trig.principal_value', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:25.759Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af3571bdcaca0a4b492abed5fff9252d', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_coord_geo_chord_contact', 'Coordinate Geometry', 'Chord of contact', '["math_12_ja_conic_sections"]', '["chord of contact","tangents","circle","polar line","geometric properties"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2850, 'JEE_ADV_HARD', 5, -2.0, 'For the circle x² + y² = 9, an external point P(5,0) is given. Which of the following statements are correct?
(A) The equation of the chord of contact of the tangents from P is x = 9/5.
(B) The length of this chord of contact is 24/5.
(C) The chord of contact passes through the origin.
(D) The chord of contact is perpendicular to the line joining P to the centre of the circle.', '["The equation of the chord of contact of the tangents from P is x = 9/5.", "The length of this chord of contact is 24/5.", "The chord of contact passes through the origin.", "The chord of contact is perpendicular to the line joining P to the centre of the circle."]', '["THE EQUATION OF THE CHORD OF CONTACT OF THE TANGENTS FROM P IS X = 9/5.", "THE LENGTH OF THIS CHORD OF CONTACT IS 24/5.", "THE CHORD OF CONTACT IS PERPENDICULAR TO THE LINE JOINING P TO THE CENTRE OF THE CIRCLE."]', 'Using the polar (chord of contact) formula T = 0 for the circle x² + y² = r², we get xx₁ + yy₁ = r² ⇒ 5x = 9 ⇒ x = 9/5. Substituting this x‑value into the circle gives y = ±12/5, so the chord length = 2·12/5 = 24/5. The chord is a vertical line, while the line OP is horizontal; thus they are perpendicular. The chord does not pass through the origin.', '["Step 1: Apply the chord of contact formula T = 0: xx₁ + yy₁ = r², with (x₁,y₁) = (5,0) and r = 3.", "Step 2: Obtain 5x = 9 ⇒ x = 9/5, the equation of the chord of contact.", "Step 3: Find intersection points with the circle: substitute x = 9/5 into x² + y² = 9 to get y = ±12/5.", "Step 4: Compute the distance between (9/5, 12/5) and (9/5, -12/5) → length = 24/5.", "Step 5: Observe that the chord is vertical while OP is horizontal, confirming perpendicularity; note that the origin (0,0) does not satisfy x = 9/5."]', 'T = 0: xx₁ + yy₁ = r²', 'math.coord_geo.chord_contact.sign_error', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:51.575Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af396af7b843690d71b89dde3d705752', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vectors', 'Vector Algebra', 'Addition subtraction magnitude direction', '[]', '["vector subtraction","magnitude of vector","unit vectors","Cartesian components","vector algebra"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, 0.0, 'Two vectors $\vec{A} = 3\hat{i} + 4\hat{j}$ and $\vec{B} = -4\hat{i} + 3\hat{j}$ are given. What is the magnitude of $\vec{A} - \vec{B}$?', '[]', '7', '$\vec{A} - \vec{B} = (7\hat{i} + \hat{j})$, magnitude $= \sqrt{49 + 1} = \sqrt{50} \approx 7.07$, nearest integer 7.', '["Step 1: Compute $\\vec{A} - \\vec{B} = (3+4)\\hat{i} + (4-3)\\hat{j} = 7\\hat{i} + \\hat{j}$", "Step 2: $|\\vec{A}-\\vec{B}| = \\sqrt{7^2 + 1^2} = \\sqrt{50} \\approx 7.07$", "Step 3: Round to nearest integer: 7"]', '|\vec{A} - \vec{B}| = \sqrt{(A_x - B_x)^2 + (A_y - B_y)^2}', 'math.vectors.magnitude_rounding', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:32.881Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af3a0a142003dc65f87a915a50ff7517', 'Board', '10', 'Science', 'sci_10_board_magnetic_generator', 'Magnetic Effects of Current', 'Electric generator (AC) principle', '[]', '["generator","alternating current","Faraday''s law","emf","coil","magnetic flux","rotation frequency"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 5, 0.0, 'A simple hand‑cranked generator consists of a rectangular coil of 20 turns rotating in a uniform magnetic field of 0.2 T. The coil has an area of 0.01 m² and rotates at 5 rev s⁻¹. Which type of voltage does the generator produce, and what is its peak value?', '["Alternating voltage, peak \\approx 1.3 V", "Direct voltage, peak \\approx 1.3 V", "Alternating voltage, peak \\approx 0.63 V", "Direct voltage, peak \\approx 0.63 V"]', 'Alternating voltage, peak \approx 1.3 V', 'A rotating coil in a magnetic field generates an alternating emf given by $\varepsilon_{\max}=N B A \omega$. Here $\omega = 2\pi f = 2\pi\times5 = 10\pi\,\text{rad s}^{-1}$. Substituting $N=20$, $B=0.2\,\text{T}$, $A=0.01\,\text{m}^2$ gives $\varepsilon_{\max}=20\times0.2\times0.01\times10\pi = 0.4\pi \approx 1.26\,\text{V}$, i.e., about 1.3 V AC.', '["Step 1: Identify that a rotating coil produces an alternating emf (Faraday''s law).", "Step 2: Write the peak emf formula $\\varepsilon_{\\max}=N B A \\omega$.", "Step 3: Compute the angular speed $\\omega = 2\\pi f = 2\\pi\\times5 = 10\\pi\\,\\text{rad s}^{-1}$.", "Step 4: Substitute $N=20$, $B=0.2\\,\\text{T}$, $A=0.01\\,\\text{m}^2$, $\\omega=10\\pi$ to get $\\varepsilon_{\\max}=0.4\\pi \\approx 1.26\\,\\text{V}$.", "Step 5: Conclude that the generator yields an alternating voltage with a peak of roughly 1.3 V."]', '\varepsilon_{\max}=N B A \omega', 'physics.magnetism.generator_ac', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:55:40.170Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af3aadc3059d1c687d43048477078c69', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Classification of Carbohydrates', '[]', '["polysaccharide","glycosidic_bond","carbohydrate_polymer","biomolecule_classification"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following statements about polysaccharides is correct?', '["They are composed of repeating monosaccharide units linked by glycosidic bonds.", "They consist of only two monosaccharide units.", "They are always water‑soluble.", "They are composed of amino acids."]', 'They are composed of repeating monosaccharide units linked by glycosidic bonds.', 'Polysaccharides are long chains formed by many monosaccharide residues joined through glycosidic linkages. They may be soluble or insoluble depending on structure, but the defining feature is the repetitive carbohydrate units.', '["Step 1: Recall the definition of a polysaccharide.", "Step 2: Identify that it is a polymer of monosaccharides.", "Step 3: Recognize the role of glycosidic bonds in linking the units.", "Step 4: Eliminate options that describe disaccharides, proteins, or solubility assumptions."]', '', 'chemistry.organic.biomolecule_classification', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:37.705Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af3c335748b7a0a49143b1ca049c9702', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'Permutations and Combinations', 'Circular permutation with restriction', '["math_11_jm_circular_permutation"]', '["circular permutation","restriction","gap method","arrangement","fixing position","factorial"]', 1, 0, '[]', 'MCQ', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 5, -1.0, 'The number of ways in which 6 boys and 6 girls can be seated around a circular table so that no two girls are adjacent is:', '["$5! \\times 6!$", "$6! \\times 6!$", "$11!$", "$(6!)^2$"]', '$5! \times 6!$', 'First fix one boy''s position (circular permutation). Arrange remaining 5 boys in $5!$ ways. This creates 6 gaps between boys where girls can sit. Place 6 girls in these 6 gaps in $6!$ ways. So total arrangements = $5! \times 6!$.', '["Step 1: Fix one boy to break circular symmetry", "Step 2: Arrange remaining 5 boys in $5!$ ways", "Step 3: Identify 6 gaps between boys for girls", "Step 4: Arrange 6 girls in these gaps in $6!$ ways", "Step 5: Multiply: $5! \\times 6!$"]', 'Circular arrangements with restrictions: fix one, create gaps', 'math.pnc.circular_fix_position', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:54.174Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af3e5219229bdc587f748055f2570704', 'JEEMains', '12', 'Physics', 'phy_12_jm_moving_charges_and_magnetism', 'Moving Charges and Magnetism', 'Cyclotron motion radius period', '[]', '["Cyclotron","Particle Accelerator","Magnetic Field"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'A cyclotron is a type of particle accelerator that uses a magnetic field to steer charged particles in a circular path. Find the radius of the cyclotron motion.', '["$$r = \\frac{mv}{qB}$$", "$$r = \\frac{mv}{qE}$$", "$$r = \\frac{mv}{qB^2}$$", "$$r = \\frac{mv}{qE^2}$$"]', '$$r = \frac{mv}{qB}$$', 'Step 1: Recall the formula for the radius of the cyclotron motion: $$r = \frac{mv}{qB}$$,Step 2: Evaluate the expression: $$r = \frac{mv}{qB}$$', '["Step 1: Apply the formula for the radius of the cyclotron motion", "Step 2: Evaluate the expression"]', 'r = \frac{mv}{qB}', 'physics.moving_charges.cyclotron', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:25.301Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af42b9878a34293b5567f930492545de', 'Board', '10', 'Science', 'bio_10_life_excretion', 'Life Processes', 'Excretion', '[]', '["nephron","proximal tubule","glucose reabsorption","renal physiology","filtration"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 4, 0.0, 'In the human nephron, which segment is primarily responsible for reabsorbing about 65% of the filtered glucose from the glomerular filtrate?', '["Proximal convoluted tubule", "Loop of Henle", "Distal convoluted tubule", "Collecting duct"]', 'Proximal convoluted tubule', 'Glucose is reabsorbed almost completely in the proximal convoluted tubule via Na⁺‑glucose cotransporters. About 65 % of the filtered glucose load is reclaimed here, leaving little to be reabsorbed later.', '["Step 1: Identify the nephron segment where most solute reabsorption occurs.", "Step 2: Recall that glucose reabsorption is handled by Na⁺‑glucose transporters in the proximal tubule.", "Step 3: Match the percentage (≈65 %) with the proximal convoluted tubule.", "Step 4: Choose the corresponding option."]', '', 'biology.excretion.nephron_glucose_reabsorption', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:05.892Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af42cf113b0941f8c6c3fac3eca5b64b', 'Board', '10', 'Science', 'bio_10_sc_life_processes_transportation_in_plants_xylem_phloem', 'Life Processes', 'Transportation in plants xylem phloem', '[]', '["Xylem","Phloem","Vascular tissue"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 2, 0.0, '$\text{The xylem and phloem are the two types of vascular tissues found in plants. The xylem is responsible for transporting:}$', '["Water and minerals", "Food and nutrients", "Oxygen and carbon dioxide", "Waste products"]', 'Water and minerals', 'The xylem transports water and minerals from the roots to the leaves.', '["Step 1: Identify the function of the xylem in plants.", "Step 2: Analyze the options to determine the correct answer."]', '', 'biology.life_processes.transportation_in_plants_xylem_phloem', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_life_proc', '2026-05-22T14:53:33.719Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('af454c7de1677dd6df8dee30119e02ab', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_equilibrium', 'Equilibrium', 'Degree of dissociation', '[]', '["weak acid","degree of dissociation","Ka calculation","Ostwald dilution"]', 0, 0, '[]', 'Integer', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, 0.0, 'For a weak acid HA with initial concentration $0.1\,\text{M}$, $\alpha = 0.01$. What is $K_a$?', '[]', '1e-05', '$K_a = C\alpha^2 = 0.1 \times (0.01)^2 = 10^{-5}$', '["Step 1: Use $K_a = C\\alpha^2$", "Step 2: Plug $C=0.1$, $\\alpha=0.01$"]', '$K_a = C\alpha^2$', 'chemistry.equilibrium.alpha_squared_mistake', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:38:58.800Z', 1);
